sysevent_in_email_action.script:
(function runAction(current, event, email, logger, classifier) {

    var catalogItemSysId = '7c14aa442f5f4390a94e2a7a6fa4e3d0';

    var cart = new sn_sc.CartJS();

    var item = {
        'sysparm_id': catalogItemSysId,
        'sysparm_quantity': '1',
        'variables': {}
    };

    var asset = email.body.asset_type;
    var groupName = '';
    var assetType = '';

    if (asset == 'Computer') {
        groupName = 'Computers';
        assetType = 'computer';
    } else if (asset == 'Network Gear') {
        groupName = 'Network Gear';
        assetType = 'netgear';
    } else if (asset == 'Printer') {
        groupName = 'Printers';
        assetType = 'printer';
    } else if (asset == 'UPS') {
        groupName = 'UPS';
        assetType = 'ups';
    }

    var assignmentGroupSysId = '';
    var grGroup = new GlideRecord('sys_user_group');

    if (grGroup.get('name', groupName)) {
        assignmentGroupSysId = grGroup.getUniqueValue();
    }

    var openedBy = gs.getUserID();
    var requestor = '';
    var requestorCompany = '';
    var grUser = new GlideRecord('sys_user');

    if (grUser.get('email', email.origemail)) {
        requestor = grUser.getUniqueValue();
        requestorCompany = grUser.getValue('company') || '';
    }

    var priority = email.body.priority || '4';

    if (requestor) {
        if (grUser.getValue('vip') == '1') {
            priority = '1';
        }
    }

    var consumables = '';

    if (email.body.consumables) {
        consumables = email.body.consumables.toLowerCase().replace(/\s+/g, '_');
    }

    item.variables.requestor = requestor;
    item.variables.type_of_asset = assetType;
    item.variables.consumables = consumables;
    item.variables.assignment_group = assignmentGroupSysId;
    item.variables.opened_by = openedBy;
    item.variables.priority = priority;
    item.variables.description = email.body_text;
    item.variables.short_description = email.subject;
    item.variables.company = requestorCompany;
    item.variables.status = 'submitted';

    var cartDetails = cart.orderNow(item);

    if (cartDetails && cartDetails.request_id) {
        var emailRec = new GlideRecord('sys_email');

        if (emailRec.get(sys_email.sys_id)) {
            emailRec.target_table = 'sc_request';
            emailRec.instance = cartDetails.request_id;
            emailRec.update();
        }

        event.state = "stop_processing";
    }

})(current, event, email, logger, classifier);
